            "additionalProperties": false,
            "default": {},
            "description": "Typeorm driver.",
            "properties": {
                "database": {
                    "default": "phone",
                    "description": "Database name to connect to",
                    "type": "string"
                },
                "host": {
                    "default": "localhost",
                    "description": "Database host",
                    "type": "string"
                },
                "password": {
                    "default": "postgres",
                    "description": "Database password",
                    "type": "string"
                },
                "port": {
                    "default": 5432,
                    "description": "Database port",
                    "type": "integer"
                },
                "type": {
                    "default": "postgres",
                    "description": "Database type, sync with typeorm.DriverType",
                    "enum": [
                        "mysql",
                        "postgres",
                        "mariadb",
                        "sqlite",
                        "oracle",
                        "mssql",
                        "websql"
                    ],
                    "type": "string"
                },
                "username": {
                    "default": "postgres",
                    "description": "Database username",
                    "type": "string"
                }
            },
            "required": [
                "type",
                "host",
                "port",
                "username",
                "password",
                "database"
            ],
            "type": "object"
        },
        "value": {
            "description": "Column value.",
            "type": "string"
        }
    },
    "required": [
        "$tool",
        "dist",
        "column",
        "value",
        "driver"
    ],
